(window.GioKinhBooks=window.GioKinhBooks||{})["phap-cu"]={"id":"phap-cu","title":"Kinh Pháp Cú","by":"Việt dịch: HT Thích Minh Châu · Dhammapada · CC0","src":"https://suttacentral.net/dhp/vi/phantuananh","srcName":"SuttaCentral","chapters":[{"t":"Phẩm Song Yếu","r":"Kệ 1–20","b":[["n","Chuyện Trưởng lão Cakkhupāla (Hộ Nhãn)"],["k",1,["Ý dẫn đầu các pháp,","Ý làm chủ, ý tạo;","Nếu với ý ô nhiễm,","Nói lên hay hành động,","Khổ não bước theo sau,","Như xe, chân vật kéo."]],["n","Chuyện cậu Maṭṭhakuṇḍali (Kim Hoàn)"],["k",2,["Ý dẫn đầu các pháp,","Ý làm chủ, ý tạo;","Nếu với ý thanh tịnh,","Nói lên hay hành động,","An lạc bước theo sau,","Như bóng, không rời hình."]],["n","Chuyện Trưởng lão Tissa"],["k",3,["Nó mắng tôi, đánh tôi,","Nó thắng tôi, cướp tôi","Ai ôm hiềm hận ấy,","Hận thù không thể nguôi."]],["k",4,["Nó mắng tôi, đánh tôi,","Nó thắng tôi, cướp tôi","Không ôm hiềm hận ấy,","Hận thù được tự nguôi."]],["n","Chuyện nữ Kāḷaya (Dạ-xoa)"],["k",5,["Với hận diệt hận thù,","Đời này không có được.","Không hận diệt hận thù,","Là định luật ngàn thu."]],["n","Chuyện các Tỳ-kheo ở thành Kosambi"],["k",6,["Và người khác không biết,","Chúng ta đây bị hại.","Chỗ ấy, ai hiểu được","Tranh luận được lắng êm."]],["n","Chuyện Trưởng giả Mahākāḷa (Đại Hắc)"],["k",7,["Ai sống nhìn tịnh tướng,","Không hộ trì các căn,","ăn uống thiếu tiết độ,","biếng nhác, chẳng tinh cần.","Ma uy hiếp kẻ ấy,","như cây yếu trước gió."]],["k",8,["Ai sống quán bất tịnh,","Khéo hộ trì các căn,","ăn uống có tiết độ,","Có lòng tin, tinh cần,","Ma không uy hiếp được,","Như núi đá, trước gió."]],["n","Chuyện Devadatta (Đề-bà-đạt-đa)"],["k",9,["Ai mặc áo cà-sa.","tâm chưa rời uế trược,","không tự chế, không thực,","không xứng áo cà-sa"]],["k",10,["Ai rời bỏ uế trược,","giới luật khéo nghiêm trì,","tự chế, sống chơn thực,","thật xứng áo cà-sa."]],["n","Chuyện Trưởng lão Sāriputta (Xá-lợi-phất)"],["k",11,["Không chân, tướng chân thật,","chân thật, thấy không chân:","chúng không đạt chân thật,","do tà tư, tà hạnh."]],["k",12,["Chân thật, biết chân thật,","Không chân, biết không chân:","chúng đạt được chân thật,","do chánh tư, chánh hạnh."]],["n","Chuyện Trưởng lão Nanda"],["k",13,["Như mái nhà vụng lợp,","Mưa liền xâm nhập vào.","Cũng vậy tâm không tu,","Tham dục liền xâm nhập."]],["k",14,["Như ngôi nhà khéo lợp,","Mưa không xâm nhập vào.","Cũng vậy tâm khéo tu,","Tham dục không xâm nhập."]],["n","Chuyện đồ tể Cunda"],["k",15,["Nay sầu, đời sau sầu,","Kẻ ác, hai đời sầu;","Nó sầu, nó ưu não,","Thấy nghiệp uế mình làm."]],["n","Chuyện thiện nam tử Dhammika (Hợp Pháp)"],["k",16,["Nay vui, đời sau vui,","Làm phước, hai đời vui,","Nó vui, nó an vui,","Thấy nghiệp tịnh mình làm."]],["n","Chuyện Devadatta (Đề-bà-đạt-đa)"],["k",17,["Nay than, đời sau than,","Kẻ ác, hai đời than,","Nó than: ‘Ta làm ác’","Đọa cõi dữ, than hơn."]],["n","Chuyện nàng Sumanādevī"],["k",18,["Nay sướng, đời sau sướng,","Làm phước, hai đời sướng.","Nó sướng: ‘Ta làm thiện’,","Sanh cõi lành, sướng hơn."]],["n","Chuyện hai Tỳ-kheo bằng hữu"],["k",19,["Nếu người nói nhiều kinh,","Không hành trì, phóng dật;","Như kẻ chăn bò người,","Không phần Sa môn hạnh."]],["k",20,["Dầu nói ít kinh điển,","Nhưng hành pháp, tùy pháp,","Từ bỏ tham, sân, si,","Tĩnh giác, tâm giải thoát,","Không chấp thủ hai đời,","Dự phần Sa môn hạnh."]]]},{"t":"Phẩm Không Phóng Dật","r":"Kệ 21–32","b":[["n","Chuyện Hoàng hậu Sāmāvatī"],["k",21,["Không phóng dật, đường sống,","Phóng dật là đường chết.","Không phóng dật, không chết,","Phóng dật như chết rồi."]],["k",22,["Biết rõ sai biệt ấy,","Người trí không phóng dật,","Hoan hỷ, không phóng dật,","An vui hạnh bậc Thánh."]],["k",23,["Người hằng tu thiền định,","Thường kiên trì tinh tấn.","Bậc trí hưởng Niết-bàn,","Đạt an tịnh vô thượng."]],["n","Chuyện Thiên hộ Kumbhaghosaka (Đào Khí Âm)"],["k",24,["Nỗ lực, giữ chánh niệm,","Tịnh hạnh, hành thận trọng","Tự điều, sống theo pháp,","Ai sống không phóng dật, Tiếng lành ngày tăng trưởng."]],["n","Chuyện Trưởng lão Cūḷapanthaka (Tiểu Lộ)"],["k",25,["Nỗ lực, không phóng dật,","Tự điều, khéo chế ngự.","Bậc trí xây hòn đảo,","Nước lụt khó ngập tràn."]],["n","Chuyện cái Tết thác loạn"],["k",26,["Chúng ngu si, thiếu trí,","Chuyên sống đời phóng dật.","Người trí, không phóng dật,","Như giữ tài sản quý."]],["k",27,["Chớ sống đời phóng dật,","Chớ mê say dục lạc.","Không phóng dật, thiền định,","Đạt được an lạc lớn."]],["n","Chuyện Trưởng lão Mahā Kassapa (Ca-diếp)"],["k",28,["Người trí dẹp phóng dật,","Với hạnh không phóng dật,","Leo lầu cao trí tuệ,","Không sầu, nhìn khổ sầu,","Bậc trí đứng núi cao,","Nhìn kẻ ngu, đất bằng."]],["n","Chuyện hai Tỳ-kheo bằng hữu"],["k",29,["Tinh cần giữa phóng dật,","Tỉnh thức giữa quần mê.","Người trí như ngựa phi,","Bỏ sau con ngựa hèn."]],["n","Chuyện Magha (Đế-thích)"],["k",30,["Đế-thích không phóng dật,","Đạt ngôi vị Thiên chủ.","Không phóng dật, được khen;","Phóng dật, thường bị trách."]],["n","Chuyện vị Tỳ-kheo quán lửa rừng"],["k",31,["Vui thích không phóng dật,","Tỳ-kheo sợ phóng dật,","Bước tới như lửa hừng,","Thiêu kiết sử lớn nhỏ."]],["n","Chuyện Trưởng lão Tissa ở thị xã"],["k",32,["Vui thích không phóng dật,","Tỳ-kheo sợ phóng dật,","Không thể bị thối đọa,","Nhất định gần Niết-bàn."]]]},{"t":"Phẩm Tâm","r":"Kệ 33–43","b":[["n","Chuyện Trưởng lão Meghiya (Mê-kỳ-dạ)"],["k",33,["Tâm hoảng hốt giao động,","Khó hộ trì, khó nhiếp,","Người trí làm tâm thẳng,","Như thợ tên, làm tên."]],["k",34,["Như cá quăng lên bờ,","Vất ra ngoài thủy giới;","Tâm này vùng vẫy mạnh,","Hãy đoạn thế lực Ma."]],["n","Chuyện vị Tỳ-kheo ở làng Mātikagāma (Thủy Lưu)"],["k",35,["Khó nắm giữ, khinh động,","Theo các dục quay cuồng.","Lành thay, điều phục tâm;","Tâm điều, an lạc đến."]],["n","Chuyện vị Tỳ-kheo bất mãn"],["k",36,["Tâm khó thấy, tế nhị,","Theo các dục quay cuồng.","Người trí phòng hộ tâm,","Tâm hộ, an lạc đến."]],["n","Chuyện Trưởng lão Saṅgharakkhitabhāginey (Hộ Tăng Điệt)"],["k",37,["Chạy xa, sống một mình,","Không thân, ẩn hang sâu,","Ai điều phục được tâm,","Thoát khỏi Ma trói buộc."]],["n","Chuyện Trưởng lão Cittahattha (Phục Tâm)"],["k",38,["Ai tâm không an trú,","Không biết chân diệu pháp,","Tịnh tín bị rúng động,","Trí tuệ không viên thành."]],["k",39,["Tâm không đầy tràn dục,","Tâm không (hận) công phá,","Đoạn tuyệt mọi thiện ác,","Kẻ tỉnh không sợ hãi."]],["n","Chuyện các Tỳ-kheo quán tự ngã"],["k",40,["Biết thân như đồ gốm,","Trú tâm như thành trì,","Chống Ma với gươm trí;","Giữ chiến thắng không tham"]],["n","Chuyện Trưởng lão Tissa lở loét"],["k",41,["Không bao lâu thân này,","Sẽ nằm dài trên đất,","Bị vất bỏ, vô thức,","Như khúc cây vô dụng."]],["n","Chuyện Nanda chủ trại bò"],["k",42,["Kẻ thù hại kẻ thù,","Oan gia hại oan gia,","Không bằng tâm hướng tà,","Gây ác cho tự thân."]],["n","Chuyện Trưởng lão Soreyya (Tu-lệ-da)"],["k",43,["Điều mẹ cha bà con,","Không có thể làm được,","Tâm hướng chánh làm được","Làm được tốt đẹp hơn."]]]},{"t":"Phẩm Hoa","r":"Kệ 44–59","b":[["n","Chuyện 500 vị Tỳ-kheo đàm luận về địa đại"],["k",44,["Ai chinh phục đất này","Dạ ma, Thiên giới này?","Ai khéo giảng Pháp cú,","Như người khéo hái hoa?"]],["k",45,["Hữu học chinh phục đất,","Dạ ma, Thiên giới này.","Hữu học giảng Pháp cú,","Như người khéo hái hoa."]],["n","Chuyện vị Tỳ-kheo quán bào ảnh"],["k",46,["Biết thân như bọt nước,","Ngộ thân là như huyễn,","Bẻ tên hoa của Ma,","Vượt tầm mắt Thần chết."]],["n","Chuyện vua Viḍūḍabha (Lưu Ly)"],["k",47,["Người nhặt các loại hoa,","Ý đắm say, tham nhiễm,","Bị Thần chết mang đi,","Như lụt trôi làng ngủ."]],["n","Chuyện nàng Patipūjikā (Sự Phụ)"],["k",48,["Người nhặt các loại hoa,","Ý đắm say, tham nhiễm,","Các dục chưa thỏa mãn,","Đã bị chết chinh phục."]],["n","Chuyện bá hộ Macchariya (Khan Nang)"],["k",49,["Như ong đến với hoa,","Không hại sắc và hương,","Che chở hoa, lấy nhụy.","Bậc Thánh đi vào làng."]],["n","Chuyện tu sĩ ngoại đạo Pāṭika (Tiểu Điệp)"],["k",50,["Không nên nhìn lỗi người,","Người làm hay không làm.","Nên nhìn tự chính mình,","Có làm hay không làm."]],["n","Chuyện thiện nam tử Chattapāṇi (Tản Thủ)"],["k",51,["Như bông hoa tươi đẹp,","Có sắc nhưng không hương.","Cũng vậy, lời khéo nói,","Không làm, không kết quả."]],["k",52,["Như bông hoa tươi đẹp,","Có sắc lại thêm hương;","Cũng vậy, lời khéo nói,","Có làm, có kết quả."]],["n","Chuyện bà Visākhā (Thiện Chi)"],["k",53,["Như từ một đống hoa,","Nhiều tràng hoa được kết.","Cũng vậy, thân sanh tử,","Làm được nhiều thiện sự."]],["n","Chuyện Trưởng lão Ānanda vấn đạo"],["k",54,["Hương các loại hoa thơm","Không ngược bay chiều gió","Nhưng hương người đức hạnh Ngược gió khắp tung bay","Chỉ có bậc chân nhân Toả khắp mọi phương trời."]],["k",55,["Hoa chiên đàn, già la,","Hoa sen, hoa vũ quý.","Giữa những hương hoa ấy,","Giới hương là vô thượng."]],["n","Chuyện Trưởng lão Mahā Kassapa (Ca-diếp) được Đế-thích để bát cúng dường"],["k",56,["Ít giá trị hương này,","Hương già la, chiên đàn;","Chỉ hương người đức hạnh,","Tối thượng tỏa Thiên giới."]],["n","Chuyện Trưởng lão Godhika viên tịch"],["k",57,["Giữa ai có giới hạnh,","An trú không phóng dật.","Chánh trí, chơn giải thoát,","Ác ma không thấy đường."]],["n","Chuyện ông Garahadinna (Oán Trách Thí)"],["k",58,["Như giữa đống rác nhớp,","Quăng bỏ trên đường lớn,","Chỗ ấy hoa sen nở,","Thơm sạch, đẹp ý người."]],["k",59,["Cũng vậy giữa quần sanh,","Uế nhiễm, mù, phàm tục,","Đệ tử bậc Chánh Giác,","Sáng ngời với Tuệ Tri."]]]},{"t":"Phẩm Ngu","r":"Kệ 60–75","b":[["n","Chuyện trai nghèo có vợ đẹp"],["k",60,["Đêm dài cho kẻ thức,","Đường dài cho kẻ mệt,","Luân hồi dài, kẻ ngu,","Không biết chơn diệu pháp."]],["n","Chuyện đệ tử của Trưởng lão Mahā Kassapa (Ca-diếp)"],["k",61,["Tìm không được bạn đường,","Hơn mình hay bằng mình,","Thà quyết sống một mình,","Không làm bạn kẻ ngu."]],["n","Chuyện Trưởng giả Ānanda"],["k",62,["“Con tôi, tài sản tôi”,","Người ngu sanh ưu não,","Tự ta, ta không có,","Con đâu, tài sản đâu?"]],["n","Chuyện tên trộm"],["k",63,["Người ngu nghĩ mình ngu,","Nhờ vậy thành có trí.","Người ngu tưởng có trí,","Thật xứng gọi chí ngu."]],["n","Chuyện Trưởng lão Udāyi"],["k",64,["Người ngu, dầu trọn đời,","Thân cận người có trí,","Không biết được Chánh pháp,","Như muỗng với vị canh."]],["n","Chuyện nhóm Tỳ-kheo ở xứ Pāveyyaka"],["k",65,["Người trí, dù một khắc,","Thân cận người có trí,","Biết ngay chân diệu pháp,","Như lưỡi với vị canh."]],["n","Chuyện ông Suppabuddhakuṭṭhi (Thiện Giác cùi)"],["k",66,["Người ngu si thiếu trí,","Tự ngã thành kẻ thù.","Làm các nghiệp không thiện,","Phải chịu quả đắng cay."]],["n","Chuyện người nông phu mắc cạn"],["k",67,["Nghiệp làm không chánh thiện,","Làm rồi sanh ăn năn,","Mặt nhuốm lệ, khóc than,","Lãnh chịu quả dị thục."]],["n","Chuyện người kết tràng hoa Sumana (Hảo Ý)"],["k",68,["Và nghiệp làm chánh thiện,","Làm rồi không ăn năn,","Hoan hỷ, ý đẹp lòng,","Hưởng thọ quả dị thục."]],["n","Chuyện Thánh nữ Uppalavaṇṇā (Thanh Liên Sắc)"],["k",69,["Người ngu nghĩ là ngọt,","Khi ác chưa chín muồi;","Ác nghiệp chín muồi rồi,","Người ngu chịu khổ đau."]],["n","Chuyện tu sĩ ngoại đạo Jambūka (Hào Cẩu)"],["k",70,["Tháng tháng với ngọn cỏ,","Người ngu có ăn uống","Không bằng phần mười sáu,","Người hiểu pháp hữu vi."]],["n","Chuyện ngạ quỷ mình rắn"],["k",71,["Nghiệp ác đã được làm,","Như sữa, không đông ngay,","Cháy ngầm theo kẻ ngu,","Như lửa tro che đậy."]],["n","Chuyện ngạ quỷ bị búa đập đầu"],["k",72,["Tự nó chịu bất hạnh,","Khi danh đến kẻ ngu.","Vận may bị tổn hại,","Đầu nó bị nát tan."]],["n","Chuyện Trưởng lão Suddhamma (Thiện Pháp)"],["k",73,["Ưa danh không tương xứng,","Muốn ngồi trước tỳ-kheo,","ưa quyền tại tịnh xá,","Muốn mọi người lễ kính."]],["k",74,["“Mong cả hai tăng, tục,","Nghĩ rằng chính ta làm.","Trong mọi việc lớn nhỏ,","Phải theo mệnh lệnh ta”","Người ngu nghĩ như vậy","Dục và mạn tăng trưởng."]],["n","Chuyện Trưởng lão Tissa ở rừng Vanavāsi"],["k",75,["Khác thay duyên thế lợi,","Khác thay đường Niết-bàn.","Tỳ-kheo, đệ tử Phật,","Hãy như vậy thắng tri.","Chớ ưa thích cung kính,","Hãy tu hạnh viễn ly."]]]},{"t":"Phẩm Hiền Trí","r":"Kệ 76–89","b":[["n","Chuyện Trưởng lão Rādha"],["k",76,["Nếu thấy bậc hiền trí,","Chỉ lỗi và khiển trách,","Như chỉ chỗ chôn vàng","Hãy thân cận người trí!","Thân cận người như vậy,","Chỉ tốt hơn, không xấu."]],["n","Chuyện nhóm Tỳ-kheo Assajipunabbasuka (Ác Tăng)"],["k",77,["Những người hay khuyên dạy,","Ngăn người khác làm ác,","Được người hiền kính yêu,","Bị người ác không thích."]],["n","Chuyện Trưởng lão Channa (Sa-nặc)"],["k",78,["Chớ thân với bạn ác,","Chớ thân kẻ tiểu nhân.","Hãy thân người bạn lành,","Hãy thân bậc thượng nhân."]],["n","Chuyện Trưởng lão Mahā Kappina (Kiếp-tân-na)"],["k",79,["Pháp hỷ đem an lạc,","Với tâm tư thuần tịnh;","Người trí thường hoan hỷ,","Với pháp bậc Thánh thuyết."]],["n","Chuyện Sa-di Paṇḍita (Trí Giả)"],["k",80,["Người trị thủy dẫn nước,","Kẻ làm tên nắn tên,","Người thợ mộc uốn gỗ,","Bậc trí nhiếp tự thân."]],["n","Chuyện Trưởng lão Lakuṇṭaka Bhaddiya"],["k",81,["Như đá tảng kiên cố,","Không gió nào giao động,","Cũng vậy, giữa khen chê,","Người trí không giao động."]],["n","Chuyện mẹ nàng Kāṇā"],["k",82,["Như hồ nước sâu thẳm,","Trong sáng, không khuấy đục,","Cũng vậy, nghe chánh pháp,","Người trí hưởng tịnh lạc."]],["n","Chuyện 500 vị Tỳ-kheo"],["k",83,["Người hiền bỏ tất cả,","Người lành không bàn dục,","Dầu cảm thọ lạc khổ,","Bậc trí không vui buồn."]],["n","Chuyện Trưởng lão Dhammika (Hợp Pháp)"],["k",84,["Không vì mình, vì người. Không cầu được con cái,","Không tài sản quốc độ, Không cầu mình thành tựu,","Với việc làm phi pháp.","Vị ấy thật trì giới, Có trí tuệ, đúng pháp."]],["n","Chuyện nhóm thiện tín nghe pháp"],["k",85,["Ít người giữa nhân loại,","Đến được bờ bên kia","Còn số người còn lại,","Xuôi ngược chạy bờ này."]],["k",86,["Những ai hành trì pháp,","Theo chánh pháp khéo dạy,","Sẽ đến bờ bên kia,","Vượt ma lực khó thoát."]],["n","Chuyện 500 vị khách Tăng"],["k",87,["Kẻ trí bỏ pháp đen,","Tu tập theo pháp trắng.","Bỏ nhà, sống không nhà,","Sống viễn ly khổ lạc."]],["k",88,["Hãy cầu vui Niết-bàn,","Bỏ dục, không sở hữu,","Kẻ trí tự rửa sạch,","Cấu uế từ nội tâm."]],["k",89,["Những ai với chánh tâm,","Khéo tu tập giác chi,","Từ bỏ mọi ái nhiễm,","Hoan hỷ không chấp thủ.","Không lậu hoặc, sáng chói,","Sống tịch tịnh ở đời."]]]},{"t":"Phẩm A-la-hán","r":"Kệ 90–99","b":[["n","Chuyện ông Jīvaka"],["k",90,["Đích đã đến, không sầu,","Giải thoát ngoài tất cả,","Đoạn trừ mọi buộc ràng,","Vị ấy không nhiệt não."]],["n","Chuyện Trưởng lão Mahā Kassapa (Ca-diếp)"],["k",91,["Tự sách tấn chánh niệm,","Không thích cư xá nào,","Như ngỗng trời rời ao,","Bỏ sau mọi trú ẩn."]],["n","Chuyện Trưởng lão Belaṭṭhasīsa"],["k",92,["Tài sản không chất chứa,","Ăn uống biết liễu trì,","Tự tại trong hành xứ,","Không vô tướng, giải thoát,","Như chim giữa hư không,","Hướng chúng đi khó tìm."]],["n","Chuyện Trưởng lão Anuruddha (A-nậu-lâu-đà)"],["k",93,["Ai lậu hoặc đoạn sạch,","Ăn uống không tham đắm,","Tự tại trong hành xứ,","Không, vô tướng, giải thoát.","Như chim giữa hư không,","Dấu chân thật khó tìm."]],["n","Chuyện Trưởng lão Mahā Kaccāyana (Ca-chiên-diên)"],["k",94,["Ai nhiếp phục các căn,","Như đánh xe điều ngự,","Mạn trừ, lậu hoặc dứt,","Người vậy, Chư Thiên mến."]],["n","Chuyện Trưởng lão Sāriputta (Xá-lợi-phất)"],["k",95,["Như đất không hiềm hận,","Như cột trụ kiên trì,","Như hồ, không bùn nhơ,","Không luân hồi, vị ấy."]],["n","Chuyện Trưởng lão Tissa ở xứ Kosambi"],["k",96,["Người tâm ý an tịnh,","Lời an, nghiệp cũng an,","Chánh trí, chơn giải thoát,","Tịnh lạc là vị ấy."]],["n","Chuyện Trưởng lão Sāriputta (Xá-lợi-phất)"],["k",97,["Không tin, hiểu Vô vi.","Người cắt mọi hệ lụy,","Cơ hội tận, xả ly","Vị ấy thật tối thượng."]],["n","Chuyện Trưởng lão Revata ở rừng Keo"],["k",98,["Làng mạc hay rừng núi","Thung lũng hay đồi cao,","La-hán trú chỗ nào,","Đất ấy thật khả ái."]],["n","Chuyện người nữ quyến rũ sa-môn"],["k",99,["Khả ái thay núi rừng,","Chỗ người phàm không ưa,","Vị ly tham ưa thích,","Vì không tìm dục lạc."]]]},{"t":"Phẩm Ngàn","r":"Kệ 100–115","b":[["n","Chuyện đao phủ thủ Tambadāṭhika (Nanh Đồng)"],["k",100,["Dầu nói ngàn ngàn lời,","Nhưng không gì lợi ích,","Tốt hơn một câu nghĩa,","Nghe xong, được tịnh lạc."]],["n","Chuyện Trưởng lão Bāhiya mặc y vỏ cây"],["k",101,["Dầu nói ngàn câu kệ","Nhưng không gì lợi ích,","Tốt hơn nói một câu,","Nghe xong, được tịnh lạc."]],["n","Chuyện Trưởng lão ni Kuṇḍalakesī (Tóc Quăn)"],["k",102,["Dầu nói trăm câu kệ","Nhưng không gì lợi ích","Tốt hơn một câu Pháp,","Nghe xong, được tịnh lạc."]],["k",103,["Dầu tại bãi chiến trường","Thắng ngàn ngàn quân địch,","Tự thắng mình tốt hơn,","Thật chiến thắng tối thượng."]],["n","Chuyện thầy Bà-la-môn hỏi về pháp Vô ích"],["k",104,["Tự thắng , tốt đẹp hơn,","Hơn chiến thắng người khác.","Người khéo điều phục mình,","Thường sống tự chế ngự."]],["k",105,["Dầu Thiên Thần, Thát-bà,","Dầu Ma Vương, Phạm Thiên","Không ai chiến thắng nổi,","Người tự thắng như vậy."]],["n","Chuyện thầy Bà-la-môn họ hàng Trưởng lão Sāriputta (Xá-lợi-phất)"],["k",106,["Tháng tháng bỏ ngàn vàng,","Tế tự cả trăm năm,","Chẳng bằng trong giây lát,","Cúng dường bậc tự tu.","Cúng dường vậy tốt hơn,","Hơn trăm năm tế tự."]],["n","Chuyện thầy Bà-la-môn họ hàng Trưởng lão Sāriputta (Xá-lợi-phất)"],["k",107,["Dầu trải một trăm năm,","Thờ lửa tại rừng sâu,","Chẳng bằng trong giây lát,","Cúng dường bậc tự tu.","Cúng dường vậy tốt hơn,","Hơn trăm năm tế tự."]],["n","Chuyện thầy Bà-la-môn bạn Trưởng lão Sāriputta (Xá-lợi-phất)"],["k",108,["Suốt năm cúng tế vật,","Để cầu phước ở đời.","Không bằng một phần tư","Kính lễ bậc chánh trực."]],["n","Chuyện cậu bé Dīghāyu (Trường Thọ)"],["k",109,["Thường tôn trọng, kính lễ","Bậc kỳ lão trưởng thượng,","Bốn pháp được tăng trưởng:","Thọ, sắc, lạc, sức mạnh."]],["n","Chuyện Sa-di Saṅkicca (Đòn Xóc)"],["k",110,["Dầu sống một trăm năm,","Ác giới, không thiền định,","Tốt hơn sống một ngày,","Trì giới, tu thiền định."]],["n","Chuyện Trưởng lão Khāṇukoñdañña (Kiều-trần-như Gốc Cây)."],["k",111,["Ai sống một trăm năm,","Ác tuệ, không thiền định.","Tốt hơn sống một ngày,","Có tuệ, tu thiền định."]],["n","Chuyện Trưởng lão Sappadāsa"],["k",112,["Ai sống một trăm năm,","Lười nhác không tin tấn,","Tốt hơn sống một ngày","Tinh tấn tận sức mình."]],["n","Chuyện Trường lão ni Paṭācārā (Sa Đọa)"],["k",113,["Ai sống một trăm năm,","Không thấy pháp sinh diệt,","Tốt hơn sống một ngày,","Thấy được pháp sinh diệt."]],["n","Chuyện nàng Kisāgotamī"],["k",114,["Ai sống một trăm năm,","Không thấy câu bất tử,","Tốt hơn sống một ngày,","Thấy được câu bất tử."]],["n","Chuyện Trưởng lão ni Bahuputtikā (Đa Tử)"],["k",115,["Ai sống một trăm năm,","Không thấy Pháp Tối thượng,","Tốt hơn sống một ngày,","Thấy được Pháp Tối thượng."]]]},{"t":"Phẩm Ác","r":"Kệ 116–128","b":[["n","Chuyện Bà-la-môn Cūḷekasātaka (Tiểu Trung Y)"],["k",116,["Hãy gấp làm điều lành,","Ngăn tâm làm điều ác.","Ai chậm làm việc lành,","Ý ưa thích việc ác."]],["n","Chuyện Trưởng lão Seyyasaka"],["k",117,["Nếu người làm điều ác,","Chớ tiếp tục làm thêm.","Chớ ước muốn điều ác,","Chứa ác, tất chịu khổ."]],["n","Chuyện Thiên nữ Lājā (Cốm Rang)"],["k",118,["Nếu người làm điều thiện,","Nên tiếp tục làm thêm.","Hãy ước muốn điều thiện,","Chứa thiện, được an lạc."]],["n","Chuyện Trưởng giả Anāthapiṇḍika (Cấp Cô Độc)"],["k",119,["Người ác thấy là hiền.","Khi ác chưa chín muồi,","Khi ác nghiệp chín muồi,","Người ác mới thấy ác."]],["k",120,["Người hiền thấy là ác,","Khi thiện chưa chín muồi,","Khi thiện nghiệp chín muồi,","Người hiền thấy là thiện."]],["n","Chuyện vị Tỳ-khoe khinh giới nhỏ"],["k",121,["Chớ chê khinh điều ác,","Cho rằng “chưa đến mình”,","Như nước nhỏ từng giọt,","Rồi bình cũng đầy tràn.","Người ngu chứa đầy ác","Do chất chứa dần dần."]],["n","Chuyện Bá hộ Biḷālapādaka (Chân Mèo)"],["k",122,["Chớ chê khinh điều thiện","Cho rằng “chưa đến mình”,","Như nước nhỏ từng giọt,","Rồi bình cũng đầy tràn.","Người trí chứa đầy thiện,","Do chất chứa dần dần."]],["n","Chuyện phú thương tránh hiểm lộ"],["k",123,["Ít bạn đường, nhiều tiền,","Người buôn tránh đường hiểm.","Muốn sống, tránh thuốc độc,","Hãy tránh ác như vậy."]],["n","Chuyện thợ săn Kukkuṭamitta (Kê Hữu)"],["k",124,["Bàn tay không thương tích,","Có thể cầm thuốc độc.","Không thương tích, tránh độc,","Không làm, không có ác."]],["n","Chuyện thợ săn Koka gặp sa-môn"],["k",125,["Hại người không ác tâm,","Người thanh tịnh, không uế,","Tội ác đến kẻ ngu,","Như ngược gió tung bụi."]],["n","Chuyện Trưởng lão Tissa và người thợ ngọc thị giả"],["k",126,["Một số sinh bào thai,","Kẻ ác sinh địa ngục,","Người thiện lên cõi trời,","Vô lậu chứng Niết-bàn."]],["n","Chuyện 3 nhóm Tỳ-kheo"],["k",127,["Không trên trời, giữa biển,","Không lánh vào động núi,","Không chỗ nào trên đời,","Trốn được quả ác nghiệp."]],["n","Chuyện vua Suppabuddhasakka (Thiện Giác)"],["k",128,["Không trên trời, giữa biển,","Không lánh vào động núi,","Không chỗ nào trên đời,","Trốn khỏi tay thần chết."]]]},{"t":"Phẩm Hình Phạt","r":"Kệ 129–145","b":[["n","Chuyện 6 vị Tỳ-kheo hành hun"],["k",129,["Mọi người sợ hình phạt,","Mọi người sợ tử vong.","Lấy mình làm ví dụ","Không giết, không bảo giết."]],["n","Chuyện 6 vị Tỳ-kheo đe doạ"],["k",130,["Mọi người sợ hình phạt,","Mọi người thương sống còn;","Lấy mình làm ví dụ,","Không giết, không bảo giết."]],["n","Chuyện lũ trẻ đập rắn"],["k",131,["Chúng sanh cầu an lạc,","Ai dùng trượng hại người,","Để tìm lạc cho mình,","Đời sau không được lạc."]],["k",132,["Chúng sanh cầu an lạc,","Không dùng trượng hại người,","Để tìm lạc cho mình,","Đời sau hưởng được lạc."]],["n","Chuyện Trưởng lão Koṇḍadhāna"],["k",133,["Chớ nói lời ác độc,","Nói ác, bị nói lại,","Khổ thay lời phẫn nộ,","Đao trượng phản chạm người."]],["k",134,["Nếu tự mình yên lặng,","Như chiếc chuông bị bể.","Người đã chứng Niết-bàn","Người không còn phẫn nộ."]],["n","Chuyện bát quan trai giới của các tín nữ"],["k",135,["Với gậy người chăn bò,","Lùa bò ra bãi cỏ;","Cũng vậy, già và chết,","Lùa người đến mạng chung."]],["n","Chuyện ngạ quỷ mình trăn"],["k",136,["Người ngu làm điều ác,","Không ý thức việc làm.","Do tự nghiệp, người ngu","Bị nung nấu, như lửa."]],["n","Chuyện Trưởng lão Mahā Moggallāna (Mục-kiền-liên)"],["k",137,["Dùng trượng phạt không trượng","Làm ác người không ác.","Trong mười loại khổ đau,","Chịu gấp một loại khổ:"]],["k",138,["Hoặc khổ thọ khốc liệt,","Thân thể bị thương vong,","Hoặc thọ bệnh kịch liệt,","Hay loạn ý tán tâm."]],["k",139,["Hoặc tai vạ từ vua,","Hay bị vu trọng tội;","Bà con phải ly tán,","Tài sản bị nát tan."]],["k",140,["Hoặc phòng ốc nhà cửa","Bị hỏa tai thiêu đốt;","Khi thân hoại mạng chung,","Ác tuệ sanh địa ngục."]],["n","Chuyện vị Tỳ-kheo có nhiều vật dụng"],["k",141,["Không phải sống lõa thể Bện tóc, tro trét mình,","Tuyệt thực, lăn trên đất,","Sống nhớp, siêng ngồi xổm,","Làm con người được sạch, Nếu không trừ nghi hoặc."]],["n","Chuyện quan đại thần Santati"],["k",142,["Ai sống tự trang sức,","Nhưng an tịnh, nhiếp phục, Sống kiên trì, phạm hạnh,","Không hại mọi sinh linh.","Vị ấy là phạm chí, Hay sa môn, khất sĩ."]],["n","Chuyện Trưởng lão Pilotika (Khố Rách)"],["k",143,["Thật khó tìm ở đời,","Người biết thẹn, tự chế,","Biết tránh né chỉ trích","Như ngựa hiền tránh roi."]],["k",144,["Như ngựa hiền chạm roi,","Hãy nhiệt tâm, hăng hái,","Với tín, giới, tinh tấn,","Thiền định cùng trạch pháp.","Minh hạnh đủ, chánh niệm,","Đoạn khổ này vô lượng."]],["n","Chuyện Sa-di Sukha (Hạnh Phúc)"],["k",145,["Người trị thủy dẫn nước,","Kẻ làm tên nắn tên,","Người thợ mộc uốn ván,","Bậc tự điều, điều thân."]]]},{"t":"Phẩm Già","r":"Kệ 146–156","b":[["n","Chuyện những người bạn của bà Visākhā (Thiện Chi)"],["k",146,["Cười gì, hân hoan gì,","Khi đời mãi bị thiêu?","Bị tối tăm bao trùm,","Sao không tìm ngọn đèn?"]],["n","Chuyện kỹ nữ Sirimā"],["k",147,["Hãy xem bong bóng đẹp,","Chỗ chất chứa vết thương,","Bệnh hoạn nhiều suy tư,","Thật không gì trường cửu."]],["n","Chuyện Trưởng lão ni Uttarā"],["k",148,["Sắc này bị suy già,","Ổ tật bệnh, mỏng manh,","Nhóm bất tịnh đổ vỡ,","Chết chấm dứt mạng sống."]],["n","Chuyện nhóm Tỳ-kheo tăng thượng mạn"],["k",149,["Như trái bầu mùa thu,","Bị vất bỏ quăng đi,","Nhóm xương trắng bồ câu,","Thấy chúng còn vui gì?"]],["n","Chuyện Trưởng lão ni Rūpanandā (Sắc Khánh Hỷ)"],["k",150,["Thành này làm bằng xương,","Quét tô bằng thịt máu,","Ở đây già và chết,","Mạn, lừa đảo chất chứa."]],["n","Chuyện hoàng hậu Mallikā (Mạt-lỵ) băng hà"],["k",151,["Xe vua đẹp cũng già,","Thân này rồi sẽ già.","Pháp bậc thiện, không già.","Như vậy bậc chí thiện Nói lên cho bậc thiện."]],["n","Chuyện Trưởng lão Lāḷudāyī"],["k",152,["Người ít nghe kém học,","Lớn già như trâu đực.","Thịt nó tuy lớn lên,","Nhưng tuệ không tăng trưởng."]],["n","Chuyện Phật thành đạo"],["k",153,["Lang thang bao kiếp sống","Ta tìm nhưng chẳng gặp,","Người xây dựng nhà này,","Khổ thay, phải tái sanh."]],["k",154,["Ôi! Người làm nhà kia Nay ta đã thấy ngươi!","Người không làm nhà nữa.","Đòn tay ngươi bị gẫy,","Kèo cột ngươi bị tan","Tâm ta đạt tịch diệt,","Tham ái thảy tiêu vong."]],["n","Chuyện bá hộ Mahādhana (Cự Phú)"],["k",155,["Lúc trẻ, không phạm hạnh,","Không tìm kiếm bạc tiền.","Như cò già bên ao,","Ủ rũ, không tôm cá."]],["k",156,["Lúc trẻ, không phạm hạnh,","Không tìm kiếm bạc tiền.","Như cây cung bị gãy,","Thở than những ngày qua."]]]},{"t":"Phẩm Tự Ngã","r":"Kệ 157–166","b":[["n","Chuyện vương tử Bodhi (Bồ-đề)"],["k",157,["Nếu biết yêu tự ngã,","Phải khéo bảo vệ mình,","Người trí trong ba canh,","Phải luôn tỉnh thức."]],["n","Chuyện Trưởng lão Upananda"],["k",158,["Trước hết tự đặt mình,","Vào những gì thích đáng.","Sau mới giáo hóa người,","Người trí khỏi bị nhiễm."]],["n","Chuyện Trưởng lão Padhānikatissa (Tissa Tinh Tấn Thiền)"],["k",159,["Hãy tự làm cho mình,","Như điều mình dạy người.","Khéo tự điều, điều người,","Khó thay tự điều phục!"]],["n","Chuyện mẹ của Trưởng lão Kumārakassapa (Ca-diếp Đồng Tử)"],["k",160,["Tự mình y chỉ mình,","Nào có y chỉ khác.","Nhờ khéo điều phục mình,","Được y chỉ khó được."]],["n","Chuyện thiện nam tử Mahākāla"],["k",161,["Điều ác mình tự làm,","Tự mình sanh, mình tạo.","Nghiền nát kẻ ngu si,","Như kim cương, ngọc báu."]],["n","Chuyện Devadatta (Đề-bà-đạt-đa)"],["k",162,["Phá giới quá trầm trọng,","Như dây leo bám cây","Gieo hại cho tự thân,","Như kẻ thù mong ước."]],["n","Chuyện Devadatta (Đề-bà-đạt-đa) cố ý chia rẽ Tăng"],["k",163,["Dễ làm các điều ác,","Dễ làm tự hại mình.","Còn việc lành, việc tốt,","Thật tối thượng khó làm."]],["n","Chuyện Trưởng lão Kāla"],["k",164,["Kẻ ngu si miệt thị,","Giáo pháp bậc La-hán,","Bậc Thánh, bậc chánh mạng.","Chính do ác kiến này,","Như quả loại cây lau","Mang quả tự hoại diệt."]],["n","Chuyện thiện nam tử Cūḷakāla"],["k",165,["Tự mình, điều ác làm","Tự mình làm nhiễm ô,","Tự mình, ác không làm,","Tự mình làm thanh tịnh.","Tịnh, không tịnh tự mình,","Không ai thanh tịnh ai!"]],["n","Chuyện Trưởng lão Attadattha (Tự Lợi)"],["k",166,["Dầu lợi người bao nhiêu,","Chớ quên phần tư lợi,","Nhờ thắng trí tư lợi.","Hãy chuyên tâm lợi mình."]]]},{"t":"Phẩm Thế Gian","r":"Kệ 167–178","b":[["n","Chuyện vị Tỳ-kheo trẻ"],["k",167,["Chớ theo pháp hạ liệt.","Chớ sống mặc, buông lung;","Chớ tin theo tà kiến,","Chớ tăng trưởng tục trần."]],["n","Chuyện vua Suddhodana  (Tịnh Phạn)"],["k",168,["Nỗ lực, chớ phóng dật!","Hãy sống theo chánh hạnh;","Người chánh hạnh hưởng lạc,","Cả đời này, đời sau."]],["k",169,["Hãy khéo sống chánh hạnh,","Chớ sống theo tà hạnh!","Người chánh hạnh hưởng lạc,","Cả đời này, đời sau."]],["n","Chuyện 500 vị Tỳ-kheo tu thiền quán"],["k",170,["Hãy nhìn như bọt nước,","Hãy nhìn như cảnh huyển!","Quán nhìn đời như vậy,","Thần chết không bắt gặp."]],["n","Chuyện vương tử Abhaya"],["k",171,["Hãy đến nhìn đời này,","Như xe vua lộng lẫy,","Người ngu mới tham đắm,","Kẻ trí nào đắm say."]],["n","Chuyện Trưởng lão Sammajjana"],["k",172,["Ai sống trước buông lung,","Sau sống không phóng dật,","Chói sáng rực đời này.","Như trăng thoát mây che."]],["n","Chuyện Trưởng lão Angulimāla"],["k",173,["Ai dùng các hạnh lành,","Làm xóa mờ nghiệp ác,","Chói sáng rực đời này,","Như trăng thoát mây che."]],["n","Chuyện con gái người thợ dệt"],["k",174,["Đời này thật mù quáng,","Ít kẻ thấy rõ ràng.","Như chim thoát khỏi lưới,","Rất ít đi thiên giới."]],["n","Chuyện 30 vị Tỳ-kheo"],["k",175,["Như chim thiên nga bay,","Thần thông liệng giữa trời;","Chiến thắng ma, ma quân,","Kẻ trí thoát đời này."]],["n","Chuyện nàng Ciñcamāṇavikā"],["k",176,["Ai vi phạm một pháp,","Ai nói lời vọng ngữ,","Ai bác bỏ đời sau,","Không ác nào không làm."]],["n","Chuyện cuộc thi đại thí vô song của vua Pasenadi (Ba-tư-nặc)"],["k",177,["Keo kiết không sanh thiên,","Kẻ ngu ghét bố thí,","Người trí thích bố thí,","Đời sau, được hưởng lạc."]],["n","Chuyện thanh niên Kāla, con Trưởng giả Anāthapiṇḍika (Cấp Cô Độc)"],["k",178,["Hơn thống lãnh cõi đất,","Hơn được sanh cõi trời,","Hơn chủ trì vũ trụ,","Quả Dự Lưu tối thắng."]]]},{"t":"Phẩm Phật-đà","r":"Kệ 179–196","b":[["n","Chuyện 3 con gái Ma Vương"],["k",179,["Vị chiến thắng không bại,","Vị bước đi trên đời, Không dấu tích chiến thắng,","Phật giới rộng mênh mông,","Ai dùng chân theo dõi Bậc không để dấu tích?"]],["k",180,["Ai giải tỏa lưới tham,","Ái phược hết dắt dẫn,","Phật giới rộng mênh mông,","Ai dùng chân theo dõi Bậc không để dấu tích?"]],["n","Chuyện thể hiện thần thông nhiếp phục ngoại đạo"],["k",181,["Người trí chuyên thiền định,","Thích an tịnh viễn ly,","Chư thiên đều ái kính,","Bậc chánh giác, chánh niệm."]],["n","Chuyện long vương Erakapatta."],["k",182,["Khó thay, được làm người,","Khó thay, được sống còn,","Khó thay, nghe Diệu Pháp,","Khó thay, Phật ra đời!"]],["n","Chuyện Trưởng lão Ānanda vấn đạo"],["k",183,["Không làm mọi điều ác.","Thành tựu các hạnh lành,","Tâm ý giữ trong sạch,","Chính lời chư Phật dạy."]],["k",184,["Chư Phật thường giảng dạy; Nhẫn, khổ hạnh tối thượng;","Niết-bàn quả tối thượng;","Xuất gia không phá người;","Sa môn không hại người."]],["k",185,["Không phỉ báng, phá hoại,","Hộ trì giới căn bản,","Ăn uống có tiết độ,","Sàng tọa chỗ nhàn tịnh","Chuyên chú tăng thượng tâm,","Chính lời chư Phật dạy."]],["n","Chuyện vị Tỳ-kheo không hoan hỷ"],["k",186,["Dầu mưa bằng tiền vàng,","Các dục khó thỏa mãn.","Dục đắng nhiều ngọt ít,","Biết vậy là bậc trí."]],["k",187,["Đệ tử bậc chánh giác,","Không tìm cầu dục lạc,","Dầu là dục chư thiên,","Chỉ ưa thích ái diệt."]],["n","Chuyện quốc sư Aggidatta"],["k",188,["Loài người sợ hoảng hốt,","Tìm nhiều chỗ quy y,","Hoặc rừng rậm, núi non,","Hoặc vườn cây, đền tháp."]],["k",189,["Quy y ấy không ổn,","Không quy y tối thượng.","Quy y các chỗ ấy,","Không thoát mọi khổ đau?"]],["k",190,["Ai quy y Đức Phật,","Chánh Pháp và chư Tăng,","Ai dùng chánh tri kiến,","Thấy được bốn Thánh đế."]],["k",191,["Thấy khổ và khổ tập,","Thấy sự khổ vượt qua,","Thấy đường Thánh tám ngành,","Đưa đến khổ não tận."]],["k",192,["Thật quy y an ổn,","Thật quy y tối thượng,","Có quy y như vậy,","Mới thoát mọi khổ đau."]],["n","Chuyện Trưởng lão Ānanda vấn đạo"],["k",193,["Khó gặp bậc thánh nhân,","Không phải đâu cũng có.","Chỗ nào bậc trí sanh,","Gia đình tất an lạc."]],["n","Chuyện chư Tỳ-kheo"],["k",194,["Vui thay, Phật ra đời!","Vui thay, Pháp được giảng!","Vui thay, Tăng hòa hợp!","Hòa hợp tu, vui thay!"]],["n","Chuyện bảo tháp Phật Kassapa (Ca-diếp)"],["k",195,["Cúng dường bậc đáng cúng,","Chư Phật hoặc đệ tử,","Các bậc vượt hý luận,","Đoạn diệt mọi sầu bi."]],["k",196,["Cúng dường bậc như vậy,","Tịch tịnh, không sợ hãi,","Các công đức như vậy,","Không ai ước lường được."]]]},{"t":"Phẩm An Lạc","r":"Kệ 197–208","b":[["n","Chuyện 2 vương tộc tranh giành vương quốc"],["k",197,["Vui thay, chúng ta sống,","Không hận, giữa hận thù!","Giữa những người thù hận,","Ta sống, không hận thù!"]],["k",198,["Vui thay, chúng ta sống,","Không bệnh giữa ốm đau!","Giữa những người bệnh hoạn,","Ta sống, không ốm đau."]],["k",199,["Vui thay, chúng ta sống,","Không rộn giữa rộn ràng;","Giữa những người rộn ràng,","Ta sống, không rộn ràng."]],["n","Chuyện Ma Vương quấy phá Đức Phật"],["k",200,["Vui thay chúng ta sống,","Không gì, gọi của ta.","Ta sẻ hưởng hỷ lạc,","Như chư thiên Quang Âm."]],["n","Chuyện vua Pasenadi (Ba-tư-nặc) nước Kosala  (Câu-tát-la) bại trận"],["k",201,["Chiến thắng sinh thù oán,","Thất bại chịu khổ đau,","Sống tịch tịnh an lạc.","Bỏ sau mọi thắng bại."]],["n","Chuyện thiếu nữ gia giáo"],["k",202,["Lửa nào sánh lửa tham?","Ác nào bằng sân hận?","Khổ nào sánh khổ uẩn,","Lạc nào bằng tịnh lạc."]],["n","Chuyện thiện nam tử nghèo được thọ thực cúng Phật"],["k",203,["Đói ăn, bệnh tối thượng,","Các hành, khổ tối thượng,","Hiểu như thực là vậy,","Niết-bàn, lạc tối thượng."]],["n","Chuyện vua Pasenadi (Ba-tư-nặc) bớt ăn"],["k",204,["Không bệnh, lợi tối thượng,","Biết đủ, tiền tối thượng.","Thành tín đối với nhau, Là bà con tối thượng,","Niết-bàn, lạc tối thượng."]],["n","Chuyện Trưởng lão Tissa"],["k",205,["Đã nếm vị độc cư,","Được hưởng vị nhàn tịnh,","Không sợ hãi, không ác,","Nếm được vị pháp hỷ."]],["n","Chuyện Đế-thích chăm sóc Phật"],["k",206,["Lành thay, thấy thánh nhân,","Sống chung thường hưởng lạc.","Không thấy những người ngu,","Thường thường được an lạc."]],["k",207,["Sống chung với người ngu,","Lâu dài bị lo buồn.","Khổ thay gần người ngu,","Như thường sống kẻ thù.","Vui thay, gần người trí,","Như chung sống bà con."]],["k",208,["Do vậy:","Bậc hiền sĩ, trí tuệ","Bậc nghe nhiều, trì giới, Bậc tự chế, Thánh nhân;","Hãy gần gũi, thân cận Thiện nhân, trí giả ấy,","Như trăng theo đường sao."]]]},{"t":"Phẩm Hỷ Ái","r":"Kệ 209–220","b":[["n","Chuyện gia đình 3 người xuất gia"],["k",209,["Tự chuyên, không đáng chuyên","Không chuyên, việc đáng chuyên","Bỏ đích, theo hỷ ái,","Ganh tị bậc tự chuyên."]],["k",210,["Chớ gần gũi người yêu,","Trọn đời xa kẻ ghét.","Yêu không gặp là khổ,","Oán phải gặp cũng đau."]],["k",211,["Do vậy chớ yêu ai,","Ái biệt ly là ác;","Những ai không yêu ghét,","Không thể có buộc ràng."]],["n","Chuyện người gia trưởng khóc con"],["k",212,["Do ái sinh sầu ưu,","Do ái sinh sợ hãi,","Ai thoát khỏi tham ái,","Không sầu, đâu sợ hãi?"]],["n","Chuyện bà Visākhā (Thiện Chi)"],["k",213,["Ái luyến sinh sầu ưu,","Ái luyến sinh sợ hãi.","Ai giải thoát ái luyến","Không sầu, đâu sợ hãi?"]],["n","Chuyện các vương tử Licchavī giành kỹ nữ"],["k",214,["Hỷ ái sinh sầu ưu,","Hỷ ái sinh sợ hãi.","Ai giải thoát hỷ ái,","Không sầu, đâu sợ hãi?"]],["n","Chuyện thanh niên Anitthāgandha (không quen hơi nữ nhân)"],["k",215,["Dục ái sinh sầu ưu,","Dục ái sinh sợ hãi,","Ai thoát khỏi dục ái,","Không sầu, đâu sợ hãi?"]],["n","Chuyện người Bà-la-môn thất hứa"],["k",216,["Tham ái sinh sầu ưu,","Tham ái sinh sợ hãi.","Ai giải thoát tham ái,","Không sầu, đâu sợ hãi?"]],["n","Chuyện 500 cậu bé cúng dâng bánh"],["k",217,["Đủ giới đức, chánh kiến;","Trú pháp, chứng chân lý,","Tự làm công việc mình,","Được quần chúng ái kính."]],["n","Chuyện vị Tỳ-kheo chứng quả A-na-hàm"],["k",218,["Ước vọng pháp ly ngôn","Ý cảm xúc thượng quả","Tâm thoát ly các dục,","Xứng gọi bậc Thượng Lưu."]],["n","Chuyện chàng Nandiya"],["k",219,["Khách lâu ngày ly hương,","An toàn từ xa về,","Bà con cùng thân hữu,","Hân hoan đón chào mừng."]],["k",220,["Cũng vậy các phước nghiệp,","Đón chào người làm lành,","Đời này đến đời kia.","Như thân nhân, đón chào."]]]},{"t":"Phẩm Phẫn Nộ","r":"Kệ 221–234","b":[["n","Chuyện Tỳ-kheo-ni Rohinī"],["k",221,["Bỏ phẫn nộ, ly mạn,","Vượt qua mọi kiết sử,","Không chấp trước danh sắc.","Khổ không theo vô sản."]],["n","Chuyện Tỳ-kheo đốn cây rừng"],["k",222,["Ai chận được phẫn nộ,","Như dừng xe đang lăn,","Ta gọi người đánh xe,","Kẻ khác, cầm cương hờ."]],["n","Chuyện tín nữ Uttarā"],["k",223,["Lấy không giận thắng giận,","Lấy thiện thắng không thiện,","Lấy thí thắng xan tham,","Lấy chơn thắng hư ngụy."]],["n","Chuyện Trưởng lão Mahā Moggallāna (Mục-kiền-liên) vấn đạo"],["k",224,["Nói thật, không phẫn nộ,","Của ít, thí người xin,","Nhờ ba việc lành này,","Người đến gần thiên giới."]],["n","Chuyện chư Tăng vấn đạo"],["k",225,["Bậc hiền không hại ai,","Thân thường được chế ngự","Đạt được cảnh bất tử,","Đến đây, không ưu sầu."]],["n","Chuyện nữ tỳ Puṇṇa"],["k",226,["Những người thường giác tỉnh,","Ngày đêm siêng tu học,","Chuyên tâm hướng Niết bàn,","Mọi lậu hoặc được tiêu."]],["n","Chuyện thiện nam tử Atula"],["k",227,["A-tu-la, nên biết,","Xưa vậy, nay cũng vậy,","Ngồi im, bị người chê,","Nói nhiều, bị người chê,","Nói vừa phải, bị chê.","Làm người không bị chê, Thật khó tìm ở đời."]],["k",228,["Xưa, vị lai, và nay,","Đâu có sự kiện này,","Người hoàn toàn bị chê,","Người trọn vẹn được khen."]],["k",229,["Sáng sáng, thẩm xét kỹ.","Bậc có trí tán thán.","Bậc trí không tỳ vết,","Đầy đủ giới định tuệ."]],["k",230,["Hạnh sáng như vàng ròng,","Ai dám chê vị ấy?","Chư thiên phải khen thưởng,","Phạm Thiên cũng tán dương."]],["n","Chuyện 6 vị Tỳ-kheo"],["k",231,["Giữ thân đừng phẫn nộ,","Phòng thân khéo bảo vệ,","Từ bỏ thân làm ác,","Với thân làm hạnh lành."]],["k",232,["Giữ lời đừng phẫn nộ,","Phòng lời khéo bảo vệ,","Từ bỏ lời thô ác,","Với lời, nói điều lành."]],["k",233,["Giữ ý đừng phẫn nộ,","Phòng ý, khéo bảo vệ,","Từ bỏ ý nghĩ ác,","Với ý, nghĩ hạnh lành."]],["k",234,["Bậc trí bảo vệ thân,","Bảo vệ luôn lời nói","Bảo vệ cả tâm tư,","Ba nghiệp khéo bảo vệ."]]]},{"t":"Phẩm Cấu Uế","r":"Kệ 235–255","b":[["n","Chuyện con người bán bò"],["k",235,["Ngươi nay giống lá héo,","Diêm sứ đang chờ ngươi,","Ngươi đứng trước cửa chết,","Đường trường thiếu tư lương."]],["k",236,["Hãy tự làm hòn đảo,","Tinh cần gấp, sáng suốt.","Trừ cấu uế, thanh tịnh,","Đến Thánh địa chư Thiên."]],["k",237,["Đời ngươi nay sắp tàn,","Tiến gần đến Diêm Vương.","Giữa đường không nơi nghỉ,","Đường trường thiếu tư lương."]],["k",238,["Hãy tự làm hòn đảo,","Tinh cần gấp, sáng suốt.","Trừ cấu uế, thanh tịnh,","Chẳng trở lại sanh già."]],["n","Chuyện người Bà-la-môn tuần tự"],["k",239,["Bậc trí theo tuần tự.","Từng sát na trừ dần","Như thợ vàng lọc bụi","Trừ cấu uế nơi mình."]],["n","Chuyện Trưởng lão Tissa"],["k",240,["Như sét từ sắt sinh,","Sắt sanh lại ăn sắt,","Cũng vậy, quá lợi dưỡng","Tự nghiệp dẫn cõi ác."]],["n","Chuyện Trưởng lão Lāḷudāyī"],["k",241,["Không tụng làm nhớp kinh,","Không đứng dậy, bẩn nhà,","Biếng nhác làm nhơ sắc,","Phóng dật uế người canh."]],["n","Chuyện người chồng có vợ ngoại tình"],["k",242,["Tà hạnh nhơ đàn bà,","Xan tham nhớp kẻ thí,","Ác pháp là vết nhơ,","Đời này và đời sau."]],["k",243,["Trong hàng cầu uế ấy,","Vô minh, nhơ tối thượng,","Đoạn nhơ ấy, tỳ-kheo,","Thành bậc không uế nhiễm."]],["n","Chuyện Tỳ-kheo Cūḷasāri theo tà mạng"],["k",244,["Dễ thay, sống không hổ","Sống lỗ mãng như quạ,","Sống công kích huyênh hoang,","Sống liều lĩnh, nhiễm ô."]],["k",245,["Khó thay, sống xấu hổ,","Thường thường cầu thanh tịnh.","Sống vô tư, khiêm tốn,","Trong sạch và sáng suốt."]],["n","Chuyện 5 thiện nam tử"],["k",246,["Ai ở đời sát sinh,","Nói láo không chân thật,","Ở đời lấy không cho,","Qua lại với vợ người."]],["k",247,["Uống rượu men, rượu nấu,","Người sống đam mê vậy,","Chính ngay tại đời này,","Tự đào bới gốc mình."]],["k",248,["Vậy người, hãy nên biết,","Không chế ngự là ác,","Chớ để tham phi pháp,","Làm người đau khổ dài."]],["n","Chuyện Tỳ-kheo Tissa trẻ hay chê sự cúng dường"],["k",249,["Do tín tâm, hỷ tâm","Loài người mới bố thí.","Ở đây ai bất mãn","Người khác được ăn uống,","Người ấy ngày hoặc đêm,","Không đạt được tâm tịnh?"]],["k",250,["Ai cắt được, phá được,","Tận gốc nhổ tâm ấy.","Người ấy ngày hoặc đêm,","Tất đến được tâm định."]],["n","Chuyện 5 thiện nam tử"],["k",251,["Lửa nào bằng lửa tham!","Chấp nào bằng sân hận!","Lưới nào bằng lưới si!","Sông nào bằng sông ái!"]],["n","Chuyện Trưởng Giả Meṇḍaka (Miên Dương)"],["k",252,["Dễ thay thấy lỗi người,","Lỗi mình thấy mới khó.","Lỗi người ta phanh tìm,","Như sàng trấu trong gạo.","Còn lỗi mình, che đậy,","Như kẻ gian dấu bài."]],["n","Chuyện Trưởng lão Ujjhānasaññī (Ưa Bắt Lỗi)"],["k",253,["Ai thấy lỗi của người,","Thường sanh lòng chỉ trích,","Người ấy lậu hoặc tăng,","Rất xa lậu hoặc diệt."]],["n","Chuyện du sĩ Subhadda"],["k",254,["Hư không, không dấu chân,","Ngoài đây, không sa môn,","Chúng sanh thích hý luận,","Như Lai, hý luận trừ."]],["k",255,["Hư không, không dấu chân,","Ngoài đây, không sa môn.","Các hành không thường trú,","Chư Phật không dao động."]]]},{"t":"Phẩm Pháp Trụ","r":"Kệ 256–272","b":[["n","Chuyện thẩm phán"],["k",256,["Ngươi đâu phải pháp trụ,","Xử sự quá chuyên chế,","Bậc trí cần phân biệt","Cả hai chánh và tà!"]],["k",257,["Không chuyên chế, đúng pháp,","Công bằng, dắt dẫn người,","Bậc trí sống đúng pháp,","Thật xứng danh Pháp trụ."]],["n","Chuyện 6 vị Tỳ-kheo gây rối"],["k",258,["Không phải vì nói nhiều,","Mới xứng danh bậc trí.","An ổn, không oán sợ.","Thật đáng gọi bậc Trí."]],["n","Chuyện Pháp sư Ekudāna"],["k",259,["Không phải vì nói nhiều,","Mới xứng danh trì pháp,","Những ai tuy nghe ít,","Nhưng thân hành đúng pháp,","Không phóng túng chánh pháp,","Mới xứng danh trì pháp."]],["n","Chuyện Trưởng lão Lakuṇṭaka Bhaddiya"],["k",260,["Không phải là trưởng lão,","Nếu cho có bạc đầu.","Người chỉ tuổi tác cao,","Được gọi là “Lão ngu”."]],["k",261,["Ai chân thật, đúng pháp,","Không hại, biết chế phục,","Bậc trí không cấu uế,","Mới xứng danh “Trưởng Lão”."]],["n","Chuyện các Tỳ-kheo tham vọng"],["k",262,["Không phải nói lưu loát,","Không phải sắc mặt đẹp,","Thành được người lương thiện,","Nếu ganh, tham, dối trá."]],["k",263,["Ai cắt được, phá được","Tận gốc nhổ tâm ấy","Người trí ấy diệt sân,","Được gọi người hiền thiện."]],["n","Chuyện vè Hatthaka"],["k",264,["Đầu trọc, không Sa-môn","Nếu phóng túng, nói láo.","Ai còn đầy dục tham,","Sao được gọi Sa-môn?"]],["k",265,["Ai lắng dịu hoàn toàn,","Các điều ác lớn nhỏ,","Vì lắng dịu ác pháp,","Được gọi là Sa-môn."]],["n","Chuyện người Bà-la-môn khất sĩ"],["k",266,["Chỉ khất thực nhờ người,","Đâu phải là Tỳ-kheo!","Phải theo pháp toàn diện,","Khất sĩ không, không đủ."]],["k",267,["Ai vượt qua thiện ác,","Chuyên sống đời Phạm Hạnh,","Sống thẩm sát ở đời,","Mới xứng danh tỳ-kheo."]],["n","Chuyện ngoại đạo im lặng"],["k",268,["Im lặng nhưng ngu si,","Đâu được gọi ẩn sĩ?","Như người cầm cán cân,","Bậc trí chọn điều lành."]],["k",269,["Từ bỏ các ác pháp,","Mới thật là ẩn sĩ.","Ai thật hiểu hai đời","Mới được gọi ẩn sĩ."]],["n","Chuyện ngư dân Ariya"],["k",270,["Còn sát hại sinh linh,","Đâu được gọi Hiền thánh.","Không hại mọi hữu tình,","Mới được gọi Hiền thánh."]],["n","Chuyện các Tỳ-kheo tự mãn"],["k",271,["Chẳng phải chỉ giới cấm","Cũng không phải học nhiều,","Chẳng phải chứng thiền định,","Sống thanh vắng một mình."]],["k",272,["“Ta hưởng an ổn lạc,","Phàm phu chưa hưởng được”:","Tỳ-kheo, chớ tự tin","Khi lậu hoặc chưa diệt."]]]},{"t":"Phẩm Đạo","r":"Kệ 273–289","b":[["n","Chuyện 500 vị Tỳ-kheo luận đạo"],["k",273,["Tám chánh, đường thù thắng,","Bốn câu, lý thù thắng,","Ly tham, pháp thù thắng,","Giữa các loài hai chân, Pháp nhãn, người thù thắng."]],["k",274,["Đường này, không đường khác","Đưa đến kiến thanh tịnh.","Nếu ngươi theo đường này,","Ma quân sẽ mê loạn."]],["k",275,["Nếu ngươi theo đường này,","Đau khổ được đoạn tận.","Ta dạy ngươi con đường.","Với trí, gai chướng diệt."]],["k",276,["Ngươi hãy nhiệt tình làm,","Như Lai chỉ thuyết dạy.","Người hành trì thiền địn","Thoát trói buộc ác Ma."]],["n","Chuyện quán vô thường"],["k",277,["Tất cả hành vô thường","Với Tuệ, quán thấy vậy","Đau khổ được nhàm chán:","Chính con đường thanh tịnh."]],["n","Chuyện quán khổ"],["k",278,["Tất cả hành khổ đau","Với Tuệ, quán thấy vậy,","Đau khổ được nhàm chán:","Chính con đường thanh tịnh."]],["n","Chuyện quán vô ngã"],["k",279,["Tất cả pháp vô ngã,","Với Tuệ, quán thấy vậy,","Đau khổ được nhàm chán:","Chính con đường thanh tịnh."]],["n","Chuyện Trưởng lão Padhānakammikatissa (Tissa Tinh Cần khổ hạnh)"],["k",280,["Khi cần, không nỗ lực,","Tuy trẻ mạnh, nhưng lười","Chí nhu nhược, biếng nhác.","Với trí tuệ thụ động, Sao tìm được chánh đạo?"]],["n","Chuyện ngạ quỷ heo"],["k",281,["Lời nói được thận trọng, Tâm tư khéo hộ phòng,","Thân chớ làm điều ác","Hãy giữ ba nghiệp tịnh,","Chứng đạo thánh nhân dạy."]],["n","Chuyện Trưởng lão Poṭṭhila"],["k",282,["Tu Thiền, trí tuệ sanh,","Bỏ Thiền, trí tuệ diệt.","Biết con đường hai ngả","Đưa đến hữu, phi hữu,","Hãy tự mình nỗ lực,","Khiến trí tuệ tăng trưởng."]],["n","Chuyện các vị Tỳ-kheo già"],["k",283,["Đốn rừng không đốn cây","Từ rừng, sinh sợ hãi;","Đốn rừng và ái dục,","Tỷ kheo, hãy tịch mịch."]],["k",284,["Khi nào chưa cắt tiệt,","Ái dục giữa gái trai,","Tâm ý vẫn buộc ràng,","Như bò con vú mẹ."]],["n","Chuyện đệ tử Trưởng lão Sāriputta (Xá-lợi-phất)"],["k",285,["Tự cắt dây ái dục,","Như tay bẻ sen thu,","Hãy tu đạo tịch tịnh,","Niết-bàn, Thiện Thệ dạy."]],["n","Chuyện phú thương Mahādhana"],["k",286,["Mùa mưa ta ở đây","Đông, hạ cũng ở đây,","Người ngu tâm tưởng vậy,","Không tự giác hiểm nguy."]],["n","Chuyện nàng Kisāgotamī"],["k",287,["Người tâm ý đắm say","Con cái và súc vật,","Tử thần bắt người ấy,","Như lụt trôi hàng ngủ."]],["n","Chuyện nàng Paṭācārā"],["k",288,["Một khi tử thần đến,","Không có con che chở,","Không cha, không bà con,","Không thân thích che chở."]],["k",289,["Biết rõ ý nghĩa này,","Bậc trí lo trì giới,","Mau lẹ làm thanh tịnh,","Con đường đến Niết bàn."]]]},{"t":"Phẩm Tạp Lục","r":"Kệ 290–305","b":[["n","Chuyện hạnh nghiệp của Đức Phật"],["k",290,["Nhờ từ bỏ lạc nhỏ,","Thấy được lạc lớn hơn,","Bậc trí bỏ lạc nhỏ,","Thấy được lạc lớn hơn."]],["n","Chuyện thiếu nữ ăn trứng gà"],["k",291,["Gieo khổ đau cho người,","Mong cầu lạc cho mình,","Bị hận thù buộc ràng","Không sao thoát hận thù."]],["n","Chuyện Tỳ-kheo xứ Bhaddiyā"],["k",292,["Việc đáng làm, không làm,","Không đáng làm, lại làm,","Người ngạo mạn, phóng dật,","Lậu hoặc ắt tăng trưởng."]],["k",293,["Người siêng năng cần mẫn,","Thường thường quán thân niệm,","Không làm việc không đáng,","Gắng làm việc đáng làm,","Người tư niệm giác tỉnh,","Lậu hoặc được tiêu trừ."]],["n","Chuyện Trưởng lão Lakuṇṭaka Bhaddiy"],["k",294,["Sau khi giết mẹ cha","Giết hai vua Sát-lỵ","Giết vương quốc, quần thần","Vô ưu, Phạm chí sống."]],["k",295,["Sau khi giết mẹ cha,","Hai vua Bà-la-môn","Giết hổ tướng thứ năm","Vô ưu, Phạm chí sống."]],["n","Chuyện con trai ông Dārusākaṭika"],["k",296,["Đệ tử Gotama,","Luôn luôn tự tỉnh giác","Vô luận ngày hay đêm,","Thường tưởng niệm Phật-đà."]],["k",297,["Đệ tử Gotama,","Luôn luôn tự tỉnh giác,","Vô luận ngày hay đêm,","Thường tưởng niệm Chánh Pháp."]],["k",298,["Đệ tử Gotama,","Luôn luôn tự tỉnh giác,","Vô luận ngày hay đêm,","Thường tưởng niệm Tăng già."]],["k",299,["Đệ tử Gotama,","Luôn luôn tự tỉnh giác,","Vô luận ngày hay đêm,","Thường tưởng niệm sắc thân."]],["k",300,["Đệ tử Gotama,","Luôn luôn tự tỉnh giác,","Vô luận ngày hay đêm,","Ý vui niềm bất hại."]],["k",301,["Đệ tử Gotama,","Luôn luôn tự tỉnh giác,","Vô luận ngày hay đêm,","Ý vui tu thiền quán."]],["n","Chuyện Tỳ-kheo con vua Vajji"],["k",302,["Vui hạnh xuất gia khó,","Tại gia sinh hoạt khó,","Sống bạn không đồng, khổ,","Trôi lăn luân hồi, khổ.","Vậy chớ sống luân hồi,","Chớ chạy theo đau khổ."]],["n","Chuyện Trưởng giả Citta"],["k",303,["Tín tâm, sống giới hạnh","Đủ danh xưng tài sản,","Chỗ nào người ấy đến,","Chỗ ấy được cung kính."]],["n","Chuyện nàng Cūḷasubhaddā, con Trưởng giả Anāthapiṇḍika (Cấp Cô Độc)"],["k",304,["Người lành dầu ở xa","Sáng tỏ như núi tuyết,","Người ác dầu ở gần","Như tên bắn đêm đen."]],["n","Chuyện Trưởng lão Ekavihārī"],["k",305,["Ai ngồi nằm một mình,","Độc hành không buồn chán,","Tự điều phục một mình","Sống thoải mái rừng sâu."]]]},{"t":"Phẩm Địa Ngục","r":"Kệ 306–319","b":[["n","Chuyện nữ ngoại giáo Sundarī"],["k",306,["Nói láo đọa địa ngục","Có làm nói không làm,","Cả hai chết đồng đẳng,","Làm người, nghiệp hạ liệt."]],["n","Chuyện những khổ nhân tạo ác nghiệp"],["k",307,["Nhiều người khoác cà-sa,","Ác hạnh không nhiếp phục.","Người ác, do ác hạnh,","Phải sanh cõi Địa ngục."]],["n","Chuyện chư Tỳ-kheo trú gần sông Vaggumudā"],["k",308,["Tốt hơn nuốt hòn sắt","Cháy đỏ như than hồng,","Hơn ác giới, buông lung","Ăn đồ ăn quốc độ."]],["n","Chuyện chàng thanh niên Khemaka"],["k",309,["Bốn nạn chờ đợi người,","Phóng dật theo vợ người;","Mắc họa, ngủ không yên,","Bị chê là thứ ba, Đọa địa ngục, thứ bốn."]],["k",310,["Mắc họa, đọa ác thú,","Bị hoảng sợ, ít vui.","Quốc vương phạt trọng hình.","Vậy chớ theo vợ người."]],["n","Chuyện Tỳ-kheo đa ngôn"],["k",311,["Như cỏ sa vụng nắm,","Tất bị họa đứt tay.","Hạnh sa môn tà vạy,","Tất bị đọa địa ngục."]],["k",312,["Sống phóng đãng buông lung,","Theo giới cấm ô nhiễm,","Sống phạm hạnh đáng nghi","Sao chứng được quả lớn."]],["k",313,["Cần phải làm, nên làm","Làm cùng tận khả năng","Xuất gia sống phóng đãng,","Chỉ tăng loạn bụi đời."]],["n","Chuyện nữ nhân hờn ghen"],["k",314,["Ác hạnh không nên làm,","Làm xong, chịu khổ lụy,","Thiện hạnh, ắt nên làm,","Làm xong, không ăn năn."]],["n","Chuyện chư khách Tăng"],["k",315,["Như thành ở biên thùy,","Trong ngoài điều phòng hộ","Cũng vậy, phòng hộ mình,","Sát na chớ buông lung.","Sát na chớ buông lung.","Khi rơi vào địa ngục."]],["n","Chuyện phái Nigaṇṭha"],["k",316,["Không đáng hổ, lại hổ.","Việc đáng hổ, lại không.","Do chấp nhận tà kiến,","Chúng sanh đi ác thú."]],["k",317,["Không đáng sợ, lại sợ,","Đáng sợ, lại thấy không,","Do chấp nhận tà kiến,","Chúng sanh đi ác thú."]],["n","Chuyện môn đồ ngoại giáo"],["k",318,["Không lỗi, lại thấy lỗi,","Có lỗi, lại thấy không,","Do chấp nhận tà kiến,","Chúng sanh đi ác thú."]],["k",319,["Có lỗi, biết có lỗi,","Không lỗi, biết là không,","Do chấp nhận chánh kiến,","Chúng sanh đi cõi lành."]]]},{"t":"Phẩm Voi","r":"Kệ 320–333","b":[["n","ự tích bậc Đạo Sư"],["k",320,["Ta như voi giữa trận","Hứng chịu cung tên rơi,","Chịu đựng mọi phỉ báng.","Ác giới rất nhiều người."]],["k",321,["Voi luyện, đưa dự hội,","Ngựa luyện, được vua cưỡi,","Người luyện, bậc tối thượng","Chịu đựng mọi phỉ báng."]],["k",322,["Tốt thay, con la thuần,","Thuần chủng loài ngựa xinh.","Đại tượng, voi có ngà.","Tự điều mới tối thượng."]],["n","Chuyện vị Tỳ-kheo từng làm huấn luyện voi"],["k",323,["Chẳng phải loài cưỡi ấy,","Đưa người đến Niết bàn,","Chỉ có người tự điều,","Đến đích nhờ điều phục."]],["n","Chuyện con trai vị Bà-la-môn già"],["k",324,["Con voi tên Tài Hộ,","Phát dục, khó điều phục,","Trói buộc, không ăn uống.","Voi nhớ đến rừng voi."]],["n","Chuyện vua Pasenadi (Ba-tư-nặc)"],["k",325,["Người ưa ngủ, ăn lớn","Nằm lăn lóc qua lại,","Chẳng khác heo no bụng,","Kẻ ngu nhập thai mãi."]],["n","Chuyện Sa-di Sānu"],["k",326,["Trước tâm này buông lung,","Chạy theo ái, dục, lạc.","Nay Ta chánh chế ngự,","Như cầm móc điều voi."]],["n","Chuyện con voi Pāveyyaka"],["k",327,["Hãy vui không phóng dật,","Khéo phòng hộ tâm ý.","Kéo mình khỏi ác đạo,","Như voi bị sa lầy."]],["n","Chuyện chư Tỳ-kheo"],["k",328,["Nếu được bạn hiền trí","Đáng sống chung, hạnh lành,","Nhiếp phục mọi hiểm nguy","Hoan hỷ sống chánh niệm."]],["k",329,["Không gặp bạn hiền trí.","Đáng sống chung, hạnh lành","Như vua bỏ nước bại","Hãy sống riêng cô độc, Như voi sống rừng voi."]],["k",330,["Tốt hơn sống một mình,","Không người ngu kết bạn.","Độc thân, không ác hạnh","Sống vô tư vô lự, Như voi sống rừng voi."]],["n","Chuyện Ma Vương"],["k",331,["Vui thay, bạn lúc cần!","Vui thay, sống biết đủ,","Vui thay, chết có đức!","Vui thay, mọi khổ đoạn."]],["k",332,["Vui thay, hiếu kính mẹ,","Vui thay, hiếu kính cha,","Vui thay, kính Sa-môn,","Vui thay, kính Hiền Thánh."]],["k",333,["Vui thay, già có giới!","Vui thay, tín an trú!","Vui thay, được trí tuệ,","Vui thay, ác không làm."]]]},{"t":"Phẩm Tham Ái","r":"Kệ 334–359","b":[["n","Chuyện con cá Kapila"],["k",334,["Người sống đời phóng dật,","Ái tăng như dây leo.","Nhảy đời này đời khác,","Như vượn tham quả rừng."]],["k",335,["Ai sống trong đời này,","Bị ái dục buộc ràng","Sầu khổ sẽ tăng trưởng,","Như cỏ bi gặp mưa."]],["k",336,["Ai sống trong đời này","Ái dục được hàng phục","Sầu rơi khỏi người ấy","Như giọt nước lá sen."]],["k",337,["Đây điều lành Ta dạy,","Các người tụ họp đây,","Hãy nhổ tận gốc ái","Như nhổ gốc cỏ bi.","Chớ để ma phá hoại,","Như dòng nước cỏ lau."]],["n","Chuyện con heo nái tơ"],["k",338,["Như cây bị chặt đốn,","Gốc chưa hại vẫn bền","Ái tùy miên chưa nhổ,","Khổ này vẫn sanh hoài."]],["k",339,["Ba mươi sáu dòng ái,","Trôi người đến khả ái.","Các tư tưởng tham ái.","Cuốn trôi người tà kiến."]],["k",340,["Dòng ái dục chảy khắp,","Như giây leo mọc tràn,","Thấy giây leo vừa sanh,","Với tuệ, hãy đoạn gốc."]],["k",341,["Người đời nhớ ái dục,","Ưa thích các hỷ lạc.","Tuy mong cầu an lạc,","Chúng vẫn phải sanh già."]],["k",342,["Người bị ái buộc ràng,","Vùng vẫy và hoảng sợ, Như thỏ bị sa lưới.","Chúng sanh ái trói buộc,","Chịu khổ đau dài dài."]],["k",343,["Người bị ái buộc ràng,","Vùng vẫy và hoảng sợ, Như thỏ bị sa lưới.","Do vậy vị tỷ kheo, Mong cầu mình ly tham","Nên nhiếp phục ái dục."]],["n","Chuyện vị Tỳ-kheo hoàn tục"],["k",344,["Lìa rừng lại hướng rừng","Thoát rừng chạy theo rừng.","Nên xem người như vậy,","Được thoát khỏi buộc ràng. Lại chạy theo ràng buộc."]],["n","Chuyện khám đường"],["k",345,["Sắt, cây, gai trói buộc","Người trí xem chưa bền.","Tham châu báu, trang sức","Tham vọng vợ và con."]],["k",346,["Người có trí nói rằng: Trói buộc này thật bền.","Trì kéo xuống, lún xuống, Nhưng thật sự khó thoát.","Người trí cắt trừ nó,","Bỏ dục lạc, không màng."]],["n","Chuyện hoàng hậu Khemā"],["k",347,["Người đắm say ái dục Tự lao mình xuống dòng","Như nhện sa lưới dệt.","Người trí cắt trừ nó,","Bỏ mọi khổ, không màng."]],["n","Chuyện thiếu gia Uggasena"],["k",348,["Bỏ quá, hiện, vị lai,","Đến bờ kia cuộc đời,","Ý giải thoát tất cả,","Chớ vướng tại sanh già."]],["n","Chuyện bậc hiền trí Cūḷadhanuggaha"],["k",349,["Người tà ý nhiếp phục,","Tham sắc bén nhìn tịnh,","Người ấy ái tăng trưởng,","Làm giây trói mình chặt."]],["k",350,["Ai vui, an tịnh ý,","Quán bất tịnh, thường niệm,","Người ấy sẽ diệt ái,","Cắt đứt Ma trói buộc."]],["n","Chuyện Ma Vương"],["k",351,["Ai tới đích không sợ,","Ly ái, không nhiễm ô","Nhổ mũi tên sanh tử,","Thân này thân cuối cùng."]],["k",352,["Ái lìa, không chấp thủ","Cú pháp khéo biện tài","Thấu suốt từ vô ngại,","Hiểu thứ lớp trước sau.","Thân này thân cuối cùng","Vị như vậy được gọi, Bậc Đại trí, đại nhân."]],["n","Chuyện du sĩ Upaka"],["k",353,["Ta hàng phục tất cả, Ta rõ biết tất cả,","Không bị nhiễm pháp nào.","Ta từ bỏ tất cả Ái diệt, tự giải thoát.","Đã tự mình thắng trí, Ta gọi ai thầy ta?"]],["n","Chuyện Đế-thích"],["k",354,["Pháp thí, thắng mọi thí!","Pháp vị, thắng mọi vị!","Pháp hỷ, thắng mọi hỷ!","Ái diệt, thắng mọi khổ!"]],["n","Chuyện trưởng giả Aputtaka"],["k",355,["Tài sản hại người ngu.","Không người tìm bờ kia","Kẻ ngu vì tham giàu,","Hại mình và hại người."]],["n","Chuyện thiên tử Aṅkura"],["k",356,["Cỏ làm hại ruộng vườn,","Tham làm hại người đời.","Bố thí người ly tham,","Do vậy được quả lớn."]],["k",357,["Cỏ làm hại ruộng vườn,","Sân làm hại người đời.","Bố thí người ly sân,","Do vậy được quả lớn."]],["k",358,["Cỏ làm hại ruộng vườn,","Si làm hại người đời,","Bố thí người ly si,","Do vậy được quả lớn."]],["k",359,["Cỏ làm hại ruộng vườn,","Dục làm hại người đời.","Bố thí người ly dục,","Do vậy được quả lớn."]]]},{"t":"Phẩm Tỳ-kheo","r":"Kệ 360–382","b":[["n","Chuyện 5 vị Tỳ-kheo"],["k",360,["Lành thay, phòng hộ mắt!","Lành thay, phòng hộ tai!","Lành thay, phòng hộ mũi!","Lành thay, phòng hộ lưỡi."]],["k",361,["Lành thay phòng hộ thân!","Lành thay, phòng hộ lời,","Lành thay, phòng hộ ý.","Lành thay, phòng tất cả.","Tỳ-kheo phòng tất cả,","Thoát được mọi khổ đau."]],["n","Chuyện vị Tỳ-kheo giết hạc"],["k",362,["Người chế ngự tay chân,","Chế ngự lời và đầu,","Vui thích nội thiền định,","Độc thân, biết vừa đủ, Thật xứng gọi tỳ-kheo."]],["n","Chuyện Tỳ-kheo Kokālika"],["k",363,["Tỳ-kheo chế ngự miệng,","Vừa lời, không cống cao,","Khi trình bày pháp nghĩa,","Lời lẽ dịu ngọt ngào."]],["n","Chuyện Trưởng lão Dhammārāma"],["k",364,["Vị tỳ-kheo thích Pháp,","Mến pháp, suy tư Pháp.","Tâm tư niệm chánh Pháp,","Không rời bỏ chánh Pháp."]],["n","Chuyện 2 Tỳ-kheo đối nghịch"],["k",365,["Không khinh điều mình được,","Không ganh người khác được,","Tỳ-kheo ganh tỵ người,","Không sao chứng Thiền định."]],["k",366,["Tỳ-kheo dù được ít,","Không khinh điều mình được,","Sống thanh tịnh không nhác,","Chư thiên khen vị này."]],["n","Chuyện Bà-la-môn Pañcaggadāyaka"],["k",367,["Hoàn toàn, đối danh sắc,","Không chấp Ta, của Ta.","Không chấp, không sầu não.","Thật xứng danh Tỳ-kheo."]],["n","Chuyện chư Tỳ-kheo"],["k",368,["Tỳ-kheo trú Từ Bi,","Tín thành giáo Pháp Phật,","Chứng cảnh giới tịch tỉnh.","Các hạnh an tịnh lạc."]],["k",369,["Tỳ-kheo, tát thuyền này,","Thuyền không, nhẹ đi mau.","Trừ tham, diệt sân hận,","Tất chứng đạt Niết-bàn."]],["k",370,["Đoạn năm, từ bỏ năm,","Tu tập năm tối thượng,","Tỳ-kheo cắt năm trói,","Xứng danh vượt “bộc lưu”."]],["k",371,["Tỳ-kheo, hãy tu thiền, Chớ buông lung phóng dật,","Tâm chớ đắm say dục,","Phóng dật, nuốt sắt nóng","Bị đốt, chớ than khổ!"]],["k",372,["Không trí tuệ, không thiền,","Không thiền, không trí tuệ.","Người có thiền có tuệ,","Nhất định gần Niết-bàn."]],["k",373,["Bước vào ngôi nhà trống,","Tỳ-kheo tâm an tịnh,","Thọ hưởng vui siêu nhân,","Tịnh quán theo chánh pháp."]],["k",374,["Người luôn luôn chánh niệm,","Sự sanh diệt các uẩn,","Được hoan hỷ, hân hoan,","Chỉ bậc bất tử biết."]],["k",375,["Đây Tỳ-kheo có trí,","Tu tập pháp căn bản","Hộ căn, biết vừa đủ,","Gìn giữ căn bản giới,"]],["k",376,["Thường gần gũi bạn lành,","Sống thanh tịnh tinh cần.","Giao thiệp khéo thân thiện,","Cử chỉ mực đoan trang.","Do vậy hưởng vui nhiều,","Sẽ dứt mọi khổ đau."]],["n","Chuyện 500 vị Tỳ-kheo"],["k",377,["Như hoa Vassika,","Quăng bỏ cánh úa tàn,","Cũng vậy vị Tỳ-kheo,","Hãy giải thoát tham sân."]],["n","Chuyện Trưởng lão Santakāya"],["k",378,["Thân tịnh, lời an tịnh,","An tịnh, khéo thiền tịnh.","Tỳ-kheo bỏ thế vật,","Xứng danh bậc tịch tịnh."]],["n","Chuyện Trưởng lão Naṇgalakūṭa"],["k",379,["Tự mình chỉ trích mình,","Tự mình dò xét mình,","Tỳ-kheo tự phòng hộ,","Chánh niệm trú an lạc."]],["k",380,["Tự mình y chỉ mình,","(dị bản)","Tự mình đi đến mình,","Vậy hãy tự điều phục,","Như khách buôn ngựa hiền."]],["n","Chuyện Trưởng lão Vakkali"],["k",381,["Tỳ-kheo nhiều hân hoan,","Tịnh tín giáo pháp Phật,","Chứng cảnh giới tịch tịnh,","Các hạnh an tịnh lạc."]],["n","Chuyện Sa-di Sumana"],["k",382,["Tỳ-kheo tuy tuổi nhỏ","Siêng tu giáo pháp Phật,","Soi sáng thế gian này,","Như trăng thoát khỏi mây."]]]},{"t":"Phẩm Bà-la-môn","r":"Kệ 383–423","b":[["n","Chuyện vị Bà-la-môn có nhiều đức tin"],["k",383,["Hỡi này Bà-la-môn, Hãy tinh tấn đoạn lòng,","Từ bỏ các dục lạc,","Biết được hành đoạn diệt,","Ngươi là bậc vô vi."]],["n","Chuyện chư Tỳ-kheo"],["k",384,["Nhờ thường trú hai pháp","Đến được bờ bên kia.","Bà-la-môn có trí,","Mọi kiết sử dứt sạch."]],["n","Chuyện Ma Vương"],["k",385,["Không bờ này, bờ kia","Cả hai bờ không có,","Lìa khổ, không trói buộc","Ta gọi Bà-la-môn."]],["n","Chuyện người Bà-la-môn"],["k",386,["Tu thiền, trú ly trần","Phận sự xong, vô lậu,","Đạt được đích tối thượng,","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão Ānanda"],["k",387,["Mặt trời sáng ban ngày,","Mặt trăng sáng ban đêm.","Khí giới sáng Sát-lỵ,","Thiền định sáng Phạm chí.","Còn hào quang đức Phật,","Chói sáng cả ngày đêm."]],["n","Chuyện một người xuất gia"],["k",388,["Dứt ác gọi Phạm chí,","Tịnh hạnh gọi Sa-môn,","Tự mình xuất cấu uế,","Nên gọi bậc xuất gia."]],["n","Chuyện Trưởng lão Sāriputta (Xá-lợi-phất)"],["k",389,["Chớ có đập Phạm chí!","Phạm chí chớ đập lại!","Xấu thay đập Phạm chí","Đập trả lại xấu hơn!"]],["k",390,["Đối vị Bà-la-môn, Đây không lợi ích nhỏ.","Khi ý không ái luyến,","Tâm hại được chận đứng,","Chỉ khi ấy khổ diệt,"]],["n","Chuyện Trưởng lão ni Mahā Pajāpatigotamī"],["k",391,["Với người thân miệng ý,","Không làm các ác hạnh","Ba nghiệp được phòng hộ,","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão Sāriputta (Xá-lợi-phất)"],["k",392,["Từ ai, biết chánh pháp","Bậc Chánh Giác thuyết giảng,","Hãy kính lễ vị ấy,","Như phạm chí thờ lửa."]],["n","Chuyện Bà-la-môn Jātila"],["k",393,["Được gọi Bà-la-môn, Không vì đầu bện tóc,","Không chủng tộc, thọ sanh,","Ai thật chân, chánh, tịnh,","Mới gọi Bà-la-môn."]],["n","Chuyện Bà-la-môn Kuhaka"],["k",394,["Kẻ ngu, có ích gì","Bện tóc với da dê,","Nội tâm toàn phiền não,","Ngoài mặt đánh bóng suông."]],["n","Chuyện nàng Kisāgotamī"],["k",395,["Người mặc áo đống rác,","Gầy ốm, lộ mạch gân,","Độc thân thiền trong rừng.","Ta gọi Bà-la-môn."]],["n","Chuyện một vị Bà-la-môn"],["k",396,["Ta không gọi Phạm chí,","Vì chỗ sanh, mẹ sanh.","Chỉ được gọi tên suông","Nếu tâm còn phiền não.","Không phiền não, chấp trước","Ta gọi Bà-la-môn."]],["n","Chuyện con trai Trưởng giả Uggasena"],["k",397,["Đoạn hết các kiết sử,","Không còn gì lo sợ","Không đắm trước buộc ràng","Ta gọi Bà-la-môn"]],["n","Chuyện 2 vị Bà-la-môn"],["k",398,["Bỏ đai da, bỏ cương","Bỏ dây, đồ sở thuộc,","Bỏ then chốt, sáng suốt,","Ta gọi Bà-la-môn."]],["n","Chuyện Bà-la-môn Akkosaka Bhāradvāja"],["k",399,["Không ác ý, nhẫn chịu,","Phỉ báng, đánh, phạt hình,","Lấy nhẫn làm quân lực,","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão Sāriputta (Xá-lợi-phất)"],["k",400,["Không hận, hết bổn phận,","Trì giới, không tham ái,","Nhiếp phục, thân cuối cùng,","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão ni Uppalavaṇṇā"],["k",401,["Như nước trên lá sen,","Như hột cải đầu kim,","Người không nhiễm ái dục,","Ta gọi Bà-la-môn."]],["n","Chuyện người Bà-la-môn"],["k",402,["Ai tự trên đời này,","Giác khổ, diệt trừ khổ,","Bỏ gánh nặng, giải thoát,","Ta gọi Bà-la-môn."]],["n","Chuyện Tỳ-kheo-ni Khemā"],["k",403,["Người trí tuệ sâu xa,","Khéo biết đạo, phi đạo","Chứng đạt đích vô thượng,","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão Tissa ngụ trong núi"],["k",404,["Không liên hệ cả hai,","Xuất gia và thế tục,","Sống độc thân, ít dục,","Ta gọi Bà-la-môn."]],["n","Chuyện chư Tỳ-kheo"],["k",405,["Bỏ trượng, đối chúng sanh,","Yếu kém hay kiên cường,","Không giết, không bảo giết,","Ta gọi Bà-la-môn."]],["n","Chuyện các Sa-di"],["k",406,["Thân thiện giữa thù địch","Ôn hòa giữa hung hăng.","Không nhiễm, giữa nhiễm trước,","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão Mahā Panthaka"],["k",407,["Người bỏ rơi tham sân,","Không mạn không ganh tị,","Như hột cải đầu kim,","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão Pilindavaccha"],["k",408,["Nói lên lời ôn hòa,","Lợi ích và chân thật,","Không mất lòng một ai,","Ta gọi Bà-la-môn."]],["n","Chuyện một vị Tỳ-kheo"],["k",409,["Ở đời, vật dài, ngắn,","Nhỏ, lớn, đẹp hay xấu","Phàm không cho không lấy,","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão Sāriputta (Xá-lợi-phất)"],["k",410,["Người không có hy cầu,","Đời này và đời sau,","Không hy cầu, giải thoát,","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão Mahā Moggallāna (Mục-kiền-liên)"],["k",411,["Người không còn tham ái,","Có trí, không nghi hoặc,","Thể nhập vào bất tử,","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão Revata"],["k",412,["Người sống ở đời này","Không nhiễm cả thiện ác,","Không sầu, sạch không bụi","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão Candābha"],["k",413,["Như trăng, sạch không uế","Sáng trong và tịnh lặng,","Hữu ái, được đoạn tận,","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão Sīvali"],["k",414,["Vượt đường nguy hiểm này,","Nhiếp phục luân hồi, si,","Đến bờ kia thiền định","Không dục ái, không nghi,","Không chấp trước, tịch tịnh,","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão Sundarasamudda"],["k",415,["Ai ở đời, đoạn dục,","Bỏ nhà, sống xuất gia,","Dục hữu được đoạn tận,","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão Jaṭila"],["k",416,["Ai ở đời đoạn ái","Bỏ nhà, sống xuất gia,","Ái hữu được đoạn tận,","Ta gọi Bà-la-môn.","Chuyện Trưởng lão Jotika","(dị bản)","(dị bản)","(dị bản)","(dị bản)"]],["n","Chuyện vị Tỳ-kheo đã từng khiêu vũ"],["k",417,["Bỏ trói buộc loài người,","Vượt trói buộc cõi trời.","Giải thoát mọi buộc ràng,","Ta gọi Bà-la-môn."]],["n","Chuyện vị Tỳ-kheo đã từng khiêu vũ"],["k",418,["Bỏ điều ưa, điều ghét,","Mát lạnh, diệt sanh y","Bậc anh hùng chiến thắng, Nhiếp phục mọi thế giới,","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão Vaṅgīsa"],["k",419,["Ai hiểu rõ hoàn toàn","Sanh tử các chúng sanh,","Không nhiễm, khéo vượt qua, Sáng suốt chân giác ngộ,","Ta gọi Bà-la-môn."]],["k",420,["Với ai, loài trời, người Cùng với Càn-thát-bà,","Không biết chỗ thọ sanh","Lậu tận bậc La-hán.","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão ni Dhammadinnā"],["k",421,["Ai quá, hiện, vị lai","Không một sở hữu gì,","Không sở hữu không nắm,","Ta gọi Bà-la-môn."]],["n","Chuyện Trưởng lão Angulimāla"],["k",422,["Bậc trâu chúa, thù thắng Bậc anh hùng, đại sĩ,","Bậc chiến thắng, không nhiễm,","Bậc tẩy sạch, giác ngộ,","Ta gọi Bà-la-môn."]],["n","Chuyện Bà-la-môn Devahita"],["k",423,["Ai biết được đời trước,","Thấy thiên giới, đọa xứ,","Đạt được sanh diệt tận","Thắng trí, tự viên thành Bậc mâu-ni đạo sĩ.","Viên mãn mọi thành tựu","Ta gọi Bà-la-môn.","Hết kinh Pháp Cú"]]]}]};
